const PH_MIS_MAX=12, PH_MIS_RELOAD=6000, PH_MIS_DMG=10;    // จรวดเฮลิ: ยิงเป็นชุดคู่ เติมเร็ว · รอบ 557: 2 นัดต่อลำ

