  if(boardEl) boardEl.addEventListener('click',e=>{ if(e.target.closest('.nr-go')&&room) room.openFriends(); });
  loadCockpitImg();                                      // 🎛️ รอบ 532: ภาพห้องนักบินจริง + canvas เข็มเกจ
